"use client";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  GalleryInternalControls,
  galleryDistance,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryMotion,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface CircularSliderItem extends GalleryInternalItem {}
export interface CircularSliderProps extends GalleryInternalProps {
  items: readonly CircularSliderItem[];
  radius?: number;
  gap?: number;
  cardWidth?: number;
  drag?: boolean;
}
export function CircularSlider({
  items,
  radius = 950,
  gap = 90,
  cardWidth = 320,
  drag = true,
  index,
  defaultIndex,
  onChange,
  onSelect,
  height = 640,
  label = "Circular slider",
  className = "",
  style,
  renderCaption,
}: CircularSliderProps) {
  const env = useGalleryEnvironment();
  const width = Math.min(cardWidth, env.size.width * 0.65);
  const r = Math.max(width, Math.min(radius, env.size.width * 1.1));
  const step = (width + gap) / r;
  const motion = useGalleryMotion(
    items.length,
    { index, defaultIndex, onChange, drag, snap: true, sensitivity: width + gap },
    env,
  );
  return (
    <div
      ref={env.ref}
      {...motion.handlers}
      className={`z-ag ${className}`}
      data-gallery="circular-slider"
      data-index={motion.current}
      data-phase={motion.phase.toFixed(4)}
      tabIndex={0}
      role="region"
      aria-label={label}
      style={galleryStyle(height, {
        userSelect: drag ? "none" : undefined,
        touchAction: drag ? "pan-y" : undefined,
        cursor: drag ? "grab" : undefined,
        ...style,
      })}
    >
      <GalleryInternalStyles />
      {items.map((item, i) => {
        const d = galleryDistance(i, motion.phase, items.length);
        const a = d * step;
        const x = Math.sin(a) * r;
        const y = (1 - Math.cos(a)) * r - 45;
        return (
          <button
            type="button"
            key={item.id}
            className="z-ag-card"
            data-gallery-card={i}
            aria-label={`View ${item.title ?? `image ${i + 1}`}`}
            aria-pressed={motion.current === i}
            onClick={(event) => {
              if (event.detail === 0 || !motion.moved.current) {
                motion.choose(motion.phase + d);
                onSelect?.(item, i);
              }
            }}
            style={{
              width,
              height: width * 1.33,
              borderRadius: 6,
              transform: `translate(-50%,-50%) translate(${x}px,${y}px) rotate(${(a * 180) / Math.PI}deg)`,
              visibility: Math.abs(a) > Math.PI / 2 ? "hidden" : "visible",
              zIndex: 30 - Math.round(Math.abs(d)),
            }}
          >
            <GalleryInternalImage item={item} />
            {renderCaption && <span className="z-ag-caption">{renderCaption(item, i)}</span>}
          </button>
        );
      })}
      <GalleryInternalControls
        current={motion.current}
        count={items.length}
        onPrevious={() => motion.choose(Math.round(motion.phase) - 1)}
        onNext={() => motion.choose(Math.round(motion.phase) + 1)}
      />
    </div>
  );
}
